} else {
    regex.match("(?i).*require_ssl\\s*[:=]\\s*false.*", str)
} else {
    regex.match("(?i).*secure_transfer_required\\s*[:=]\\s*false.*", str)
} else {
    regex.match("(?i).*force_https\\s*[:=]\\s*false.*", str)
}

